class MyThread extends Thread {
    public void run() {
        try {
            Thread.sleep(1000);
            System.out.println("After sleep");
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
MyThread t = new MyThread();
t.start();

class MyThread extends Thread {
